1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Scenario {
6	  customer: Customer;
7	  steps: Step[];
8	}
9	
10	export type Step = QuoteStep | ClaimStep;
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Item {
18	  type: string;
19	  material?: string;
20	  enchantment?: number;
21	  cursed?: boolean;
22	}
23	
24	export interface ClaimStep {
25	  op: "claim";
26	  policy: number;
27	  incident: Incident;
28	}
29	
30	export interface Incident {
31	  cause: string;
32	  damages: Damage[];
33	}
34	
35	export interface Damage {
36	  itemType: string;
37	  amount: number;
38	}
39	
40	export type Result = QuoteResult | ClaimResult;
41	
42	export interface QuoteResult {
43	  premium: number;
44	}
45	
46	export interface ClaimResult {
47	  payout: number;
48	  remainingCap: number;
49	}
50	
51	export interface ScenarioResult {
52	  results: Result[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 1 / 10;
57	// Base premium for a single item of each type.
58	const UNIT_BASE_PREMIUMS: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	  rune: 25,
64	  moonstone: 25,
65	};
66	
67	const LOYALTY_YEARS_THRESHOLD = 2;
68	const LOYALTY_DISCOUNT_RATE = 2 / 10;
69	const FOLLOW_UP_DISCOUNT_RATE = 15 / 100;
70	const CURSE_SURCHARGE_RATE = 1 / 2;
71	const HIGH_ENCHANTMENT_THRESHOLD = 5;
72	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 3 / 10;
73	const BLOCK_SIZE = 3;
74	const BLOCK_BASE_PREMIUM = 60;
75	
76	const unitBasePremium = (type: string): number => UNIT_BASE_PREMIUMS[type];
77	
78	const countByType = (items: Item[]): Map<string, number> =>
79	  items.reduce(
80	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
81	    new Map<string, number>(),
82	  );
83	
84	// A building block of 3 alike components is offered at a special base premium.
85	const basePremiumForItemGroup = (type: string, count: number): number =>
86	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * unitBasePremium(type);
87	
88	const policyBasePremium = (items: Item[]): number =>
89	  [...countByType(items)].reduce(
90	    (total, [type, count]) => total + basePremiumForItemGroup(type, count),
91	    0,
92	  );
93	
94	const isHighlyEnchanted = (item: Item): boolean =>
95	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
96	
97	const surchargeRate = (item: Item): number =>
98	  (item.cursed ? CURSE_SURCHARGE_RATE : 0) +
99	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);
100	
101	// Item-specific modifiers apply to the affected item's own base premium, i.e.
102	// the unit price of its type — a block discount never shrinks a surcharge.
103	const itemSurcharge = (item: Item): number =>
104	  unitBasePremium(item.type) * surchargeRate(item);
105	
106	const itemSurcharges = (items: Item[]): number =>
107	  items.reduce((total, item) => total + itemSurcharge(item), 0);
108	
109	const isLongStanding = (customer: Customer): boolean =>
110	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
111	
112	// Policy-wide modifiers apply to the policy base premium only — never to the
113	// item surcharges. Net signed delta: a discount can outweigh the surcharge.
114	// Every quote is a first insurance for its items, regardless of customer
115	// history, so that surcharge always applies.
116	const policyAdjustmentRate = (customer: Customer, previousContracts: number): number =>
117	  FIRST_INSURANCE_SURCHARGE_RATE -
118	  (isLongStanding(customer) ? LOYALTY_DISCOUNT_RATE : 0) -
119	  (previousContracts > 0 ? FOLLOW_UP_DISCOUNT_RATE : 0);
120	
121	// Premiums round up, in the MHPCO's favour. The adjustment is added as a
122	// separate term rather than folded into a `base * 1.1` factor, which is not
123	// exact in binary floating point (100 * 1.1 === 110.00000000000001).
124	const quotePremium = (
125	  items: Item[],
126	  customer: Customer,
127	  previousContracts: number,
128	): number => {
129	  const base = policyBasePremium(items);
130	  return Math.ceil(
131	    base +
132	      itemSurcharges(items) +
133	      base * policyAdjustmentRate(customer, previousContracts) +
134	      PROCESSING_FEE,
135	  );
136	};
137	
138	const quote = (
139	  step: QuoteStep,
140	  customer: Customer,
141	  previousContracts: number,
142	): QuoteResult => ({
143	  premium: quotePremium(step.items, customer, previousContracts),
144	});
145	
146	const runStep = (
147	  step: Step,
148	  customer: Customer,
149	  previousContracts: number,
150	): Result => {
151	  switch (step.op) {
152	    case "quote":
153	      return quote(step, customer, previousContracts);
154	    default:
155	      throw new Error(`unsupported step: ${step.op}`);
156	  }
157	};
158	
159	export const runScenario = (scenario: Scenario): ScenarioResult => {
160	  let previousContracts = 0;
161	  const results = scenario.steps.map((step) => {
162	    const result = runStep(step, scenario.customer, previousContracts);
163	    if (step.op === "quote") previousContracts += 1;
164	    return result;
165	  });
166	  return { results };
167	};
