const quotePremium = (
  items: Item[],
  customer: Customer,
  isFollowUpContract: boolean,
): number => {
  const base = policyBasePremium(items);
  return Math.ceil(
    base +
      itemSurcharges(items) +
      base * policyAdjustmentRate(customer, isFollowUpContract) +
      PROCESSING_FEE,
  );
};

// State accumulated by the steps run so far. Later steps price and pay out
// against what earlier steps established, so each step reads the state it was
// run with and returns the state the next step should see.
interface ScenarioState {
  customer: Customer;
  contractsSoFar: number;
}

// A step's outcome: what to report, and how the scenario stands afterwards.
interface StepOutcome {
  result: Result;
  state: ScenarioState;
}

const quote = (step: QuoteStep, state: ScenarioState): StepOutcome => ({
  result: {
    premium: quotePremium(step.items, state.customer, state.contractsSoFar > 0),
  },
  state: { ...state, contractsSoFar: state.contractsSoFar + 1 },
});

const runStep = (step: Step, state: ScenarioState): StepOutcome => {
  switch (step.op) {
    case "quote":
      return quote(step, state);
    default:
      throw new Error(`unsupported step: ${step.op}`);
  }
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const initialState: ScenarioState = {
    customer: scenario.customer,
    contractsSoFar: 0,
  };
  const { results } = scenario.steps.reduce<{
    results: Result[];
    state: ScenarioState;
  }>(
    ({ results, state }, step) => {
      const outcome = runStep(step, state);
      return { results: [...results, outcome.result], state: outcome.state };
    },
    { results: [], state: initialState },
  );
  return { results };
};

